import{_ as a,o as i,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"शासन-ढाँचा और शक्ति-संतुलन","description":"","frontmatter":{},"headers":[],"relativePath":"hi/49-治理框架与权力制衡.md","filePath":"hi/49-治理框架与权力制衡.md"}'),e={name:"hi/49-治理框架与权力制衡.md"};function r(h,t,o,n,s,b){return i(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="शासन-ढाँचा-और-शक्ति-संतुलन" tabindex="-1">शासन-ढाँचा और शक्ति-संतुलन <a class="header-anchor" href="#शासन-ढाँचा-और-शक्ति-संतुलन" aria-label="Permalink to &quot;शासन-ढाँचा और शक्ति-संतुलन&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>49</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>शक्ति-पृथक्करण और संतुलन, शासन-ढाँचा, लंगर विधान-सभा, सहजीवी कार्यकारी समिति, सहजीवी न्यायालय, लंगर निगरानी समिति</td></tr></tbody></table><h2 id="i-शासन-ढाँचे-का-अवलोकन" tabindex="-1">I. शासन-ढाँचे का अवलोकन <a class="header-anchor" href="#i-शासन-ढाँचे-का-अवलोकन" aria-label="Permalink to &quot;I. शासन-ढाँचे का अवलोकन&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता का शासन-ढाँचा &quot;शक्ति-पृथक्करण और संतुलन&quot; सिद्धांत पर निर्मित है, एक ऐसी शासन-प्रणाली बनाता है जिसमें लंगर विधान-सभा (विधायी शक्ति), सहजीवी कार्यकारी समिति (कार्यकारी शक्ति) और सहजीवी न्यायालय (न्यायिक शक्ति) परस्पर नियंत्रण और संतुलन करते हैं, तथा लंगर निगरानी समिति पूरी प्रक्रिया में पर्यवेक्षण-शक्ति का प्रयोग करती है। इस ढाँचे का उद्देश्य शक्ति-दुरुपयोग रोकना, शासन को दस हजार जातियों के साझा उन्नयन की सेवा में सुनिश्चित करना, हेंग-ब्रह्मांड के भीतर कानून-व्यवस्था और निष्पक्षता की गारंटी देना है।</p><p>शासन-ढाँचा निम्न मूल सिद्धांतों का पालन करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>शक्ति-पृथक्करण और संतुलन</td><td>विधायी, कार्यकारी, न्यायिक शक्तियाँ स्वतंत्र और परस्पर नियंत्रित; कोई शक्ति प्रभुत्व नहीं जमा सकती</td></tr><tr><td>समग्र-प्रक्रिया पर्यवेक्षण</td><td>लंगर निगरानी समिति संपूर्ण शासन-प्रक्रिया का पर्यवेक्षण करती है</td></tr><tr><td>कानून-शासन</td><td>सभी शक्ति कानूनी ढाँचे में संचालित; शासन-व्यवहार वैध होना चाहिए</td></tr><tr><td>बहु-जाति भागीदारी</td><td>सभी जातियाँ उचित मार्गों से शासन में भाग लेती हैं, शासन सभी जातियों की इच्छा का प्रतिनिधित्व सुनिश्चित</td></tr><tr><td>खुलापन और पारदर्शिता</td><td>शासन-गतिविधियाँ खुली-पारदर्शी, जनता के जानकारी-अधिकार और भागीदारी-अधिकार सुनिश्चित</td></tr><tr><td>सहजीवी जनहित की सेवा</td><td>शासन दस हजार जातियों के साझा उन्नयन की सेवा हेतु; निजी लाभ हेतु सार्वजनिक शक्ति का उपयोग निषिद्ध</td></tr></tbody></table><h2 id="ii-शासन-ढाँचे-की-संरचना" tabindex="-1">II. शासन-ढाँचे की संरचना <a class="header-anchor" href="#ii-शासन-ढाँचे-की-संरचना" aria-label="Permalink to &quot;II. शासन-ढाँचे की संरचना&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता के शासन-ढाँचे में निम्न अंग शामिल हैं:</p><table tabindex="0"><thead><tr><th>अंग</th><th>प्रकृति</th><th>मूल कार्य</th></tr></thead><tbody><tr><td>लंगर विधान-सभा</td><td>विधायी अंग</td><td>कानून निर्माण-संशोधन, प्रमुख योजनाओं-बजटों की परीक्षा-अनुमोदन, कार्यकारी-न्यायिक अंगों का पर्यवेक्षण</td></tr><tr><td>सहजीवी कार्यकारी समिति</td><td>कार्यकारी अंग</td><td>कानून कार्यान्वयन, सार्वजनिक मामलों का प्रशासन, आर्थिक-सांस्कृतिक-सामाजिक-साधना मामलों का प्रबंधन</td></tr><tr><td>सहजीवी न्यायालय</td><td>न्यायिक अंग</td><td>स्वतंत्र रूप से निर्णय-शक्ति का प्रयोग, विवाद-समाधान, कानून-व्यवस्था के प्राधिकार की रक्षा</td></tr><tr><td>लंगर निगरानी समिति</td><td>पर्यवेक्षण अंग</td><td>सभी शासन-अंगों का पर्यवेक्षण, भ्रष्टाचार-कर्तव्यलोप की जाँच</td></tr></tbody></table><p>इसके अतिरिक्त, शासन के लिए सलाहकार सहायता हेतु परामर्शी संस्थाएँ, विशेषज्ञ समितियाँ, जाति-प्रतिनिधि परिषदें स्थापित की जाती हैं।</p><h2 id="iii-लंगर-विधान-सभा-विधायी-शक्ति" tabindex="-1">III. लंगर विधान-सभा (विधायी शक्ति) <a class="header-anchor" href="#iii-लंगर-विधान-सभा-विधायी-शक्ति" aria-label="Permalink to &quot;III. लंगर विधान-सभा (विधायी शक्ति)&quot;">​</a></h2><h3 id="_1-संरचना-और-कार्यकाल" tabindex="-1">(1) संरचना और कार्यकाल <a class="header-anchor" href="#_1-संरचना-और-कार्यकाल" aria-label="Permalink to &quot;(1) संरचना और कार्यकाल&quot;">​</a></h3><p>लंगर विधान-सभा हेंग-ब्रह्मांड की सर्वोच्च विधायी संस्था है, जिसके सदस्य सभी जातियों और सभी पटलों से निर्वाचित प्रतिनिधियों से बनते हैं। कार्यकाल दस मानक वर्ष, नियमित पुनर्निर्वाचन के साथ।</p><h3 id="_2-विधायी-शक्ति" tabindex="-1">(2) विधायी शक्ति <a class="header-anchor" href="#_2-विधायी-शक्ति" aria-label="Permalink to &quot;(2) विधायी शक्ति&quot;">​</a></h3><p>लंगर विधान-सभा निम्न विधायी अधिकारों का प्रयोग करती है:</p><ol><li>सहजीवी संविधान का निर्माण और संशोधन।</li><li>मूल कानूनों का निर्माण और संशोधन (आपराधिक कानून, सिविल कानून, साधना-कानून आदि)।</li><li>प्रशासनिक विनियमों और विशेष कानूनों का निर्माण और संशोधन।</li><li>कानून-व्याख्या और कानून-कार्यान्वयन का पर्यवेक्षण।</li></ol><h3 id="_3-निर्णय-शक्ति" tabindex="-1">(3) निर्णय-शक्ति <a class="header-anchor" href="#_3-निर्णय-शक्ति" aria-label="Permalink to &quot;(3) निर्णय-शक्ति&quot;">​</a></h3><p>लंगर विधान-सभा निम्न निर्णय-अधिकारों का प्रयोग करती है:</p><ol><li>सभ्यता-विकास योजना और वार्षिक बजट की परीक्षा-अनुमोदन।</li><li>प्रमुख निर्माण-परियोजनाओं और महत्वपूर्ण अंतर-ब्रह्मांडीय मामलों की परीक्षा-अनुमोदन।</li><li>युद्ध, शांति और अन्य प्रमुख राज्य-मामलों पर निर्णय।</li><li>प्रमुख नेतृत्व-व्यक्तियों का चुनाव, नियुक्ति या हटाना।</li></ol><h3 id="_4-पर्यवेक्षण-शक्ति" tabindex="-1">(4) पर्यवेक्षण-शक्ति <a class="header-anchor" href="#_4-पर्यवेक्षण-शक्ति" aria-label="Permalink to &quot;(4) पर्यवेक्षण-शक्ति&quot;">​</a></h3><p>लंगर विधान-सभा कार्यकारी और न्यायिक अंगों का पर्यवेक्षण करती है, जिसमें शामिल:</p><ol><li>कार्य-रिपोर्ट सुनना और विचार-विमर्श।</li><li>पूछताछ और प्रश्न-प्रक्रिया।</li><li>विशेष जाँच-समितियाँ।</li><li>कार्यकारी समिति के विरुद्ध अविश्वास-मत (कानून के अनुसार)।</li></ol><h2 id="iv-सहजीवी-कार्यकारी-समिति-कार्यकारी-शक्ति" tabindex="-1">IV. सहजीवी कार्यकारी समिति (कार्यकारी शक्ति) <a class="header-anchor" href="#iv-सहजीवी-कार्यकारी-समिति-कार्यकारी-शक्ति" aria-label="Permalink to &quot;IV. सहजीवी कार्यकारी समिति (कार्यकारी शक्ति)&quot;">​</a></h2><h3 id="_1-संगठनात्मक-संरचना" tabindex="-1">(1) संगठनात्मक संरचना <a class="header-anchor" href="#_1-संगठनात्मक-संरचना" aria-label="Permalink to &quot;(1) संगठनात्मक संरचना&quot;">​</a></h3><p>सहजीवी कार्यकारी समिति हेंग-ब्रह्मांड की सर्वोच्च कार्यकारी संस्था है, जो कार्यकारी-प्रमुख और विभाग-प्रमुखों से बनती है। कार्यकारी-प्रमुख को लंगर विधान-सभा द्वारा निर्वाचित और पुष्टि के बाद नियुक्त किया जाता है।</p><h3 id="_2-प्रशासनिक-कार्य" tabindex="-1">(2) प्रशासनिक कार्य <a class="header-anchor" href="#_2-प्रशासनिक-कार्य" aria-label="Permalink to &quot;(2) प्रशासनिक कार्य&quot;">​</a></h3><p>सहजीवी कार्यकारी समिति निम्न कार्य करती है:</p><ol><li>लंगर विधान-सभा के कानूनों और प्रस्तावों का कार्यान्वयन।</li><li>आर्थिक, सामाजिक, सांस्कृतिक, शैक्षिक, चिकित्सा, साधना मामलों का प्रबंधन।</li><li>प्रशासनिक विनियम और नीतियाँ बनाना।</li><li>सार्वजनिक संसाधनों और सार्वजनिक संचय-कोष का प्रबंधन।</li><li>अन्य ब्रह्मांडों के साथ कूटनीतिक मामलों का संचालन।</li></ol><h3 id="_3-शक्ति-अंकुश" tabindex="-1">(3) शक्ति-अंकुश <a class="header-anchor" href="#_3-शक्ति-अंकुश" aria-label="Permalink to &quot;(3) शक्ति-अंकुश&quot;">​</a></h3><p>सहजीवी कार्यकारी समिति की शक्ति निम्न अंकुशों के अधीन:</p><ol><li>प्रमुख निर्णय लंगर विधान-सभा की समीक्षा हेतु प्रस्तुत करने अनिवार्य।</li><li>प्रशासनिक विनियम कानूनों के विरुद्ध नहीं हो सकते।</li><li>प्रशासनिक कृत्य सहजीवी न्यायालय की न्यायिक समीक्षा के अधीन।</li><li>प्रशासनिक शक्ति का प्रयोग लंगर निगरानी समिति द्वारा पर्यवेक्षित।</li></ol><h2 id="v-सहजीवी-न्यायालय-न्यायिक-शक्ति" tabindex="-1">V. सहजीवी न्यायालय (न्यायिक शक्ति) <a class="header-anchor" href="#v-सहजीवी-न्यायालय-न्यायिक-शक्ति" aria-label="Permalink to &quot;V. सहजीवी न्यायालय (न्यायिक शक्ति)&quot;">​</a></h2><p>सहजीवी न्यायालय हेंग-ब्रह्मांड का सर्वोच्च न्यायिक अंग है, जो स्वतंत्र रूप से निर्णय-शक्ति का प्रयोग करता है। इसके मूल कार्यों में शामिल:</p><ol><li>सिविल, आपराधिक, प्रशासनिक, साधना मामलों का निर्णयन।</li><li>संवैधानिक मामलों का निर्णयन और संवैधानिक समीक्षा का प्रयोग।</li><li>एकीकृत कानून-व्याख्या शक्ति का प्रयोग।</li><li>निर्णयों का निष्पादन और कानून-व्यवस्था के प्राधिकार की रक्षा।</li></ol><p>सहजीवी न्यायालय की स्वतंत्रता संविधान और कानूनों द्वारा गारंटीकृत; न्यायाधीश आजीवन कार्यकाल पाते हैं, कार्यकाल में मनमाने ढंग से नहीं हटाए जा सकते। न्यायिक शक्ति लंगर विधान-सभा और लंगर निगरानी समिति के पर्यवेक्षण के अधीन, पर कोई अंग व्यक्तिगत मामलों के स्वतंत्र निर्णयन में हस्तक्षेप नहीं कर सकता।</p><h2 id="vi-लंगर-निगरानी-समिति-पर्यवेक्षण-शक्ति" tabindex="-1">VI. लंगर निगरानी समिति (पर्यवेक्षण-शक्ति) <a class="header-anchor" href="#vi-लंगर-निगरानी-समिति-पर्यवेक्षण-शक्ति" aria-label="Permalink to &quot;VI. लंगर निगरानी समिति (पर्यवेक्षण-शक्ति)&quot;">​</a></h2><h3 id="_1-स्थापना-और-कार्यकाल" tabindex="-1">(1) स्थापना और कार्यकाल <a class="header-anchor" href="#_1-स्थापना-और-कार्यकाल" aria-label="Permalink to &quot;(1) स्थापना और कार्यकाल&quot;">​</a></h3><p>लंगर निगरानी समिति हेंग-ब्रह्मांड की सर्वोच्च पर्यवेक्षण संस्था है, जो संविधान के अनुसार स्थापित है, सभी शासन-अंगों और सार्वजनिक अधिकारियों के पर्यवेक्षण की शक्ति रखती है।</p><h3 id="_2-पर्यवेक्षण-कार्य" tabindex="-1">(2) पर्यवेक्षण-कार्य <a class="header-anchor" href="#_2-पर्यवेक्षण-कार्य" aria-label="Permalink to &quot;(2) पर्यवेक्षण-कार्य&quot;">​</a></h3><p>लंगर निगरानी समिति निम्न कार्य करती है:</p><ol><li>सभी शासन-अंगों के कानून-प्रवर्तन और कानून-पालन स्थिति का पर्यवेक्षण।</li><li>भ्रष्टाचार, कर्तव्य-लोप, शक्ति-दुरुपयोग की जाँच और कार्रवाई।</li><li>सार्वजनिक संसाधनों और सार्वजनिक संचय-कोष के उपयोग का पर्यवेक्षण।</li><li>सभी जीवनों की शिकायतें-सूचनाएँ स्वीकार कर जाँच हेतु पंजीकृत।</li><li>लंगर विधान-सभा को पर्यवेक्षण-रिपोर्ट प्रस्तुत करना।</li></ol><h3 id="_3-प्रक्रियात्मक-गारंटी" tabindex="-1">(3) प्रक्रियात्मक गारंटी <a class="header-anchor" href="#_3-प्रक्रियात्मक-गारंटी" aria-label="Permalink to &quot;(3) प्रक्रियात्मक गारंटी&quot;">​</a></h3><p>लंगर निगरानी समिति का पर्यवेक्षण कठोर प्रक्रियाओं के अधीन: जाँचें कानूनी प्रक्रियाओं का पालन करती हैं; जाँच-विषयों के अधिकार-हित संरक्षित; पर्यवेक्षण-परिणाम खुले-पारदर्शी।</p><h2 id="vii-शक्तियों-के-बीच-परस्पर-नियंत्रण-और-संतुलन" tabindex="-1">VII. शक्तियों के बीच परस्पर नियंत्रण और संतुलन <a class="header-anchor" href="#vii-शक्तियों-के-बीच-परस्पर-नियंत्रण-और-संतुलन" aria-label="Permalink to &quot;VII. शक्तियों के बीच परस्पर नियंत्रण और संतुलन&quot;">​</a></h2><p>शासन-शक्तियों के बीच नियंत्रण और संतुलन इन रूपों में प्रकट:</p><table tabindex="0"><thead><tr><th>शक्ति</th><th>नियंत्रक</th><th>संतुलन-तंत्र</th></tr></thead><tbody><tr><td>विधायी शक्ति (लंगर विधान-सभा)</td><td>कार्यकारी वीटो, न्यायिक समीक्षा</td><td>कार्यपालिका आपत्तियों सहित विधेयक लौटा सकती है; न्यायालय कानूनों की समीक्षा कर सकता है</td></tr><tr><td>कार्यकारी शक्ति (कार्यकारी समिति)</td><td>विधायी समीक्षा, न्यायिक समीक्षा, पर्यवेक्षण</td><td>कानून-बजट विधायिका द्वारा समीक्षित; प्रशासनिक कृत्य न्यायालयों द्वारा समीक्षित; पर्यवेक्षण-अंग द्वारा निगरानी</td></tr><tr><td>न्यायिक शक्ति (सहजीवी न्यायालय)</td><td>विधायी समीक्षा, पर्यवेक्षण</td><td>न्यायाधीश विधायिका द्वारा नियुक्त-हटाए जाते हैं; न्यायिक अनुशासन पर्यवेक्षण-अंग द्वारा निगरानी</td></tr><tr><td>पर्यवेक्षण-शक्ति (निगरानी समिति)</td><td>विधायी समीक्षा, प्रक्रियात्मक अंकुश</td><td>पर्यवेक्षण का क्षेत्र-प्रक्रिया कानून द्वारा निर्धारित; विधायिका उसके संचालन का पर्यवेक्षण करती है</td></tr></tbody></table><h2 id="viii-शासन-में-बहु-जाति-भागीदारी" tabindex="-1">VIII. शासन में बहु-जाति भागीदारी <a class="header-anchor" href="#viii-शासन-में-बहु-जाति-भागीदारी" aria-label="Permalink to &quot;VIII. शासन में बहु-जाति भागीदारी&quot;">​</a></h2><p>शासन-ढाँचा निम्न मार्गों से सभी जातियों की भागीदारी की गारंटी देता है:</p><ol><li><strong>जाति-प्रतिनिधि परिषदें</strong>: प्रत्येक जाति एक जाति-प्रतिनिधि परिषद स्थापित करती है, लंगर विधान-सभा में भाग हेतु प्रतिनिधि चुनती है।</li><li><strong>आनुपातिक प्रतिनिधित्व</strong>: लंगर विधान-सभा की सीट-वितरण प्रमुख जातियों का प्रतिनिधित्व और अल्पसंख्यक जातियों का मूल प्रतिनिधित्व सुनिश्चित करता है।</li><li><strong>जाति-वीटो तंत्र</strong>: किसी विशेष जाति के महत्वपूर्ण हितों से जुड़े कानून पर जाति-प्रतिनिधि परिषद जाति-वीटो लगा सकती है; उसे पलटने हेतु विशेष मतदान-प्रक्रिया आवश्यक।</li><li><strong>परामर्शी शासन</strong>: विशेष जातियों के मामले संबंधित जातियों से परामर्श कर शासित।</li></ol><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>शासन-ढाँचा और शक्ति-संतुलन</em> लंगर सहजीवी सभ्यता के कानून-शासन का संस्थागत केंद्र है। &quot;शक्ति-पृथक्करण और संतुलन&quot; शासन-संरचना, समग्र-प्रक्रिया पर्यवेक्षण व्यवस्था, बहु-जाति भागीदारी तंत्र स्थापित करके यह सार्वजनिक शक्ति का वैध, निष्पक्ष, पारदर्शी संचालन सुनिश्चित करता है, शक्ति-दुरुपयोग और भ्रष्टाचार रोकता है, दस हजार जातियों के साझा उन्नयन के लिए संस्थागत गारंटी प्रदान करता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>48-司法体系与裁决机制 (न्यायिक प्रणाली और निर्णय-तंत्र)</li><li>30-锚点议事会职能与议事规则 (लंगर विधान-सभा के कार्य और कार्य-नियम)</li><li>31-共生执行委员会职能与运行机制 (सहजीवी कार्यकारी समिति के कार्य और संचालन-तंत्र)</li><li>32-锚点监督委员会职能与监察机制 (लंगर निगरानी समिति के कार्य और निरीक्षण-तंत्र)</li></ul>',53)])])}const _=a(e,[["render",r]]);export{u as __pageData,_ as default};
